set -eu
scope="$HOME/native-code-mode-capture-0219-v1"
cd "$scope/source"
python3 - <<'PY'
import pathlib,gzip,base64,hashlib
p=gzip.decompress(base64.b64decode(''))
assert hashlib.sha256(p).hexdigest()=='c5f394255f4c6d84411f9a0c866dcde321c08794d7f57b038df13116f6d4289a'
pathlib.Path('../evidence/source.patch').write_bytes(p)
PY
git apply ../evidence/source.patch
git diff --check
export CARGO_HOME="$scope/cargo-home"
export CARGO_TARGET_DIR="$scope/target"
export CARGO_BUILD_JOBS=2
export CARGO_INCREMENTAL=0
export ZIG_GLOBAL_CACHE_DIR="$scope/zig-global"
export ZIG_LOCAL_CACHE_DIR="$scope/zig-local"
export XDG_CACHE_HOME="$scope/cache"
export SHARDS_CACHE="$scope/cache/shards"
unset DYLD_LIBRARY_PATH DYLD_FALLBACK_LIBRARY_PATH SHARDS_HELPERS SHARDS_HELPERS_DIR SHARDS_INIT_BINARY SHARDS_SERVER_BINARY SHARDS_VM_BINARY
rustc --version > ../evidence/toolchain.txt
zig version >> ../evidence/toolchain.txt
uname -a >> ../evidence/toolchain.txt
git rev-parse HEAD >> ../evidence/toolchain.txt
sha256sum crates/shards/tests/common/managed_capture.rs crates/shards/tests/managed_output.rs crates/shards/tests/build.rs > ../evidence/source-hashes.txt
set +e
timeout --signal=TERM --kill-after=15s 3600s cargo test --locked -p shards --profile test-release --test build --test managed_output --no-run -j2 > ../evidence/test-build.log 2>&1
rc=$?
printf '%s\n' "$rc" > ../evidence/test-build.exit
tail -70 ../evidence/test-build.log
exit "$rc"
